#include <stdbool.h>
#include <stdint.h>

#define CELL_COUNT 12u
#define CELL_OV_TRIP_MV 4200u
#define CELL_OV_CLEAR_MV 4100u
#define CELL_OV_CONFIRM_SAMPLES 3u

typedef struct {
    uint16_t cell_mv[CELL_COUNT];
    uint8_t ov_samples;
    bool cell_ov_fault;
    bool charge_enable_request;
} Bms;

static void bms_check_cell_overvoltage(Bms *b)
{
    uint16_t max_mv = 0u;
    for (uint8_t i = 0u; i < CELL_COUNT; ++i) {
        if (b->cell_mv[i] > max_mv) {
            max_mv = b->cell_mv[i];
        }
    }

    if (max_mv >= CELL_OV_TRIP_MV) {
        if (b->ov_samples < CELL_OV_CONFIRM_SAMPLES) {
            ++b->ov_samples;
        }
    } else if (max_mv <= CELL_OV_CLEAR_MV) {
        b->ov_samples = 0u;
    }

    if (b->ov_samples >= CELL_OV_CONFIRM_SAMPLES) {
        b->cell_ov_fault = true;
        b->charge_enable_request = false;
    }

    if (max_mv <= CELL_OV_CLEAR_MV && b->ov_samples == 0u) {
        b->cell_ov_fault = false;
    }
}

void bms_10ms_task(Bms *b)
{
    bms_check_cell_overvoltage(b);
}
